    const shade3 = tone(c, "shade"), light = tone(c, "light"), deep = tone(c, "deep");
    const grow2 = (ps) => ps.map(([x2, y2]) => [x2 * 1.16, ctr[1] + (y2 - ctr[1]) * 1.16]);
    const lit15 = grow2(at(h, [[-0.42, -1], [-0.22, -1.12], [-0.02, -1.16], [-0.52, -0.8], [-0.3, -0.88], [-0.12, -0.98], [-0.6, -0.56]]));
    const dark = grow2(at(h, [[0.5, -0.88], [0.3, -1.06], [0.6, -0.62], [0.58, -0.36], [-0.6, -0.32], [0.36, -0.82], [0.12, -1]]));
    const curls = grow2(at(h, [[-0.36, -0.96], [-0.14, -1.06], [0.1, -1.1], [0.32, -0.98], [0.48, -0.74], [-0.5, -0.66], [0.54, -0.46], [-0.56, -0.44], [0.18, -0.9], [-0.24, -0.8]]));
    const mirror4 = (ps) => ps.map(([x2, y2]) => [-x2, y2]);
