      const side3 = (s) => [[s * hw2 * 0.92, y0], [s * hw2, (y0 * 2 + foot2) / 3], [s * hw2 * 0.97, (y0 + foot2 * 2) / 3], [s * hw2 * 0.8, foot2]];
      const run = [...scallop(side3(-1), ctr, amp * 0.6), ...scallop([[-hw2 * 0.8, foot2], [-hw2 * 0.3, foot2 + 0.6 * k2], [hw2 * 0.3, foot2 + 0.6 * k2], [hw2 * 0.8, foot2]], [0, -H], amp * 0.6).slice(1, -1), ...scallop(side3(1).reverse(), ctr, amp * 0.6)];
