    const seam = (e, s) => scallop([0, 1, 2, 3].map((i) => [e[0] + (s * x - e[0]) * i / 3, e[1] + (y - e[1]) * i / 3]), [s * W5 * 0.15, -H * 0.95], amp * 0.7);
