    const line3 = [[-tx4 - 0.4 * k2, -H * 0.58, 0], [-tx4 + 0.5 * k2, yl + 0.8 * k2, 0], [-W5 * 0.2, yl - 0.2 * k2], [0, yl - 0.4 * k2], [W5 * 0.2, yl - 0.2 * k2], [tx4 - 0.5 * k2, yl + 0.8 * k2, 0], [tx4 + 0.4 * k2, -H * 0.58, 0]];
