    const hole = openingPts(h, o), ground = smooth(outer, true, 1).add(smooth([...hole].reverse(), true, 1));
    const short = [[knot[0] + 1.6 * k2, knot[1] + 1.2 * k2], [knot[0] + 2.2 * k2, end - 2 * k2, 0], [knot[0] - 3 * k2, end, 0], [knot[0] - 3.4 * k2, end - 4 * k2], [knot[0] - 1.6 * k2, knot[1] + 0.4 * k2]];
    const shortPath = smooth(short, true, 1);
