    const gw2 = f.b.neckW / 2 + 3 * k2, hem = Math.min(H * 0.18, N4 + 4 * k2), jaw = 0.12, jx = openingX(h, jaw, o);
    const side3 = [[ex, -H * 0.4], [ex - 0.8 * k2, -H * 0.18], [Math.max(gw2 + 2.5 * k2, jx + 1.8 * k2), -H * 0.02], [Math.max(gw2, jx * 0.7), H * 0.05, 0]];
