        { path: lit15.slice(1).reduce((p, q) => p.add(q), lit15[0]), fill: lt4, flat: true, opacity: 0.3, clip: bpath },
        { path: y0s.map((y0) => smooth(at7(y0), false, 1)).reduce((p, q) => p.add(q)), stroke: { color: dp, width: 0.9 * k2 }, flat: true, opacity: 0.42, clip: bpath }
