      const nape = [[-nw - 1.6 * k2, -T13 + 1.2 * k2], [-nw, -T13 - 2.4 * k2], [0, -T13 - 2 * k2], [nw, -T13 - 2.4 * k2], [nw + 1.6 * k2, -T13 + 1.2 * k2], [0, -T13 + 2.2 * k2]];
