        const hx2 = (R22 * R22 - r * r + d * d) / (2 * d), hy = Math.sqrt(Math.max(0, R22 * R22 - hx2 * hx2)), a0 = Math.atan2(hy, hx2), b0 = Math.atan2(hy, hx2 - d);
