      const T13 = b.torsoL, top3 = bibTop(b), bw = Math.min(10, b.chestW * 0.28), ww = b.waistW / 2 + 2.5, len = b.thighL * 0.95, hw2 = b.hipW / 2 + 4;
      const body3 = [[-bw, top3, 0], [bw, top3, 0], [bw * 1.08, -T13 * 0.42], [ww, -T13 * 0.2, 0], [hw2, len, 0], [0, len + 1], [-hw2, len, 0], [-ww, -T13 * 0.2, 0], [-bw * 1.08, -T13 * 0.42]];
